      "passage": "Will the European Union make it? The question would have sounded strange not long ago. Now even the project's greatest cheerleaders talk of a contment facing a \"Bermuda triangle\" of debt population decline and lower growth. As well as those chronic problems, the EU faces an acute crisis in its economic core, the 16 countries that use the single currency. Markets have lOSt faith that the euro zone, s economies, weaker or stronger, will one day converge thanks t0 the discipline 0f sharing a single currency, which denies uncompetitive members the quick fix Of devaluation. Yet the debate about hOW tO save Europe's single currency from disintegration is stuck. lt is SttlCk because the euro zone, S dominant powers, France and Germany, agree on the need for greater harmonization within the euro zone, but disagree about what tO harmonlse. Germany thmks the euro must be saved by stricter rules on borrowing, spending and competitiveness, backed by quasi-automatic sanctions for governments that dO not Obey. These might include threats t0 freeze EU funds for poorer regions and EU mega-projects, and even the suspenslon Of a country's VOting ministerial councils. It insists that economic CO- ordination should involve all 27 members 0f the EU club, among whom there is a small maj ority for free-market liberalism and economic rigour; in the inner core alone, Germany fears, a small ority favour French interference. A \"southem' camp headed by France wants something different: \"European econonuc government\" within an mner core Of euro-zone members. means politicians llltervening monetary policy and a system Of redistribution from richer tO poorer members, via cheaper borrowing for governments through common Eurobonds or complete fiscal transfers. Finally, figures close t0 the French government have murmured, euro-zone members should agree 管 理 类 专 业 学 位 联 考 英 语 试 题 一 9 一 M BA 大 师 tO some fiscal and social harmonizatlon: e.g \" curbing competition in corporate-tax rates or labour costs. lt is t00 soon t0 write off the EU. lt remains the world's largest trading block. At its best, the European project is remarkably liberal: built around a single market 0f 27 rich and poor countries, its internal borders are far more open t0 goods, capital and labour than any comparable trading area. lt is an ambitious attempt t0 blunt the sharpest edges 0f globalization, and make capitalism benign.",
