      "passage": "lt is curious that Stephen Koziatek feels almost as though he has t0 justify his efforts t0 give his students a better future. Mr. Koziatek is part of something pioneering. He is a teacher at a New Hampshire high school where learmng is not something Of books and tests and mechanical memonzation, but practical. When did it become accepted wisdom that students should be able t0 name the 13th president 0f the United States but be utterly overwhelmed by a busted bike chain? As Koziatek knows, there is learning in Jt1St about eve1Ything. N0thing is necessarily gained by forcing students t0 learn geometry at a graffitied desk stuck with generations 0f discarded chewing gum. They can also learn geometry by assembling a bicycle. But he's also found a kind 0f insidious prejudice. Working with your hands is seen as almost a mark 0f inferiority. Sch001s in the family 0f vocational education \"have that stereotype...that it's for kids who can't make it academically,\" he says. On one hand that viewpoint is a logical product ofAmenca's evolution. Manufacturing is not the economic engine that it once was. The J0b security that the U.S. economy once offered t0 high school graduates has largely evaporated. More education is the new principle. We want more for our kids, and rightfully so. But the headlong push into bachelor 's degrees for all-and the subtle devaluing of anything less-nusses an important point: That's not the only thing the American economy needs. Yes, a bachelor's degree opens more doors. But even now, 54 percent ofthe jobs in the country are middle- skill jobs, such as construction and hlgh-skill manufacturing. But only 44 percent of workers are adequately trained. 管 理 类 专 业 学 位 联 考 英 语 试 题 一 3 一 M BA 大 师 ln other words, at a time when the working class has turned the country on its political head, fiustrated that the opportunity that once defined America is vanishing, one obvious solution is starmg us in the face. There is a gap working-class J0bs, but the workers wh0 need those J0bs most aren't equipped to do them. Konatek's Manchester SchooI of Technology High SchooI is trying to fill that gap. Koziatek's school is a wake-up call. When education becomes one-size-fits-all, it risks overlooking a nation's diversity 0f gifts.",
