      "passage": "管 理 类 专 业 学 位 联 考 英 语 试 题 一 8 一 M BA 大 师 TO combat the trap 0f putting a premium on being busy, Cal Newport, author 0f 刀 e 叩 w 仞 七 Rules@了 Focused Success 口 Distracted w 伊 ' / recommends building a habit 0f \"deep work \" the ability tO focus without distraction. There are a number of approaches to mastering the aft of deep work-be it lengthy retreats dedicated to a specific task; developing a daily ritual; or taking a 'journalistic\" approach to seizing moments of deep work when you can throughout the day. Whichever approach, the key is to determine your length 0f focus tlme and stick t0 it. Newp01t alSO recommends ' deep scheduling\" tO combat constant interntptions and get more done in less time. \"At any gwen point, I should have deep work scheduled for roughly the next month. Once on the calendar, I protect this time like I would a doctor, s appointment or important meeting\" he wrltes. Another approach t0 getting more done in less time is t0 rethink how you prioritize your day- in particular how we craft our t0-d0 lists. Tim Harford, author 0f 龙 5. The 尸 ow Q ／, D 丞 伊 冒 ' ／ 0 行 0 丆 0 \". il, \", points to a study in the early 1980S that divided undergraduates into two groups: some were advised tO set out monthly goals and study activities; others were tOld tO plan activities and goals in much more detail, day by day. While the researchers assumed that the well-structured daily plans would be most effective when it came t0 the execution 0f tasks, they were wrong ： the detailed daily plans demotivated students. Harford argues that inevitable distractions Often render the daily tO-dO list ineffective, while leaving room for improvisation in such a list can reap the best results. ln order tO make the most Of our focus and energy, we alSO need tO embrace downtime, or as Newport suggests, \"be lazy.' 'ldleness is not just a vacation, an indulgence or a vice; it is as indispensable tO be brain as Vitamin [[[D] is to the body... idleness] is, paradoxlcally, necessary to gettmg any work done,\" he argues. Srini PiIIay, an assistant professor of psychiatry at Harvard MedicaI S chool, believes this counter-intuitive link between downtime and productivity may be due tO the way our brains operate. When our brains switch between being focused and unfocused on a task, they tend t0 be more efficient. 'What people don 't realise is that in order t0 complete these tasks they need t0 use b0th the focus and unfocus circuits in their brain \". says Pillay. 管 理 类 专 业 学 位 联 考 英 语 试 题 一 9 一 M BA 大 师",
