      "passage": "\"Resk111ing\" is somethmg that sounds like a buzzword but is actually a requirement if we plan to have a future in which a lot of would-be workers do not get left behind. We know we are movmg into a period where the jobs in demand will change rapidly, as well the requirements of the jobs that remain. Research by the WorId Economic Forum finds that on average 42 percent 0f the \"core skills \" within j 0b roles will change by 2022. That is a ve1Y short timeline. The question 0f wh0 should pay for reskilling is a thorny one. For individual companies, the temptation is always t0 let go 0f workers whose skills are no longer in demand and replace them with those whose skills are. That does not always happen. AT&T is often given as the gold standard 0f a company that decided t0 d0 a massive reskilling program rather than go with a fire-and-hire strategy. Other companies had also pledged t0 create their own plans. When the skill mismatch is in the broader economy though, the focus usually turns to government to handle. Efforts in Canada and elsewhere have been arguably languid at best and have given us a situation where we frequently hear of employees beggmg for workers, even at times and in regions where unemployment is high. With the pandemic, unemployment is very high indeed. ln Febntary, at 3 巧 percent and 5 巧 percent respectively, unemployment rates in Canada and the U.S. were at generational IOWS and worker shortages were everywhere. As 0f May, those rates had spiked up t0 13. 3 percent and 13. 7 percent, and although many worker shortages had disappeared, not all had done so. ln medical field t0 take an obvious example. The pandemic meant that there were still clear shortages 0f doctors, nurses Other medical personnel. Of course, it is not likely you can take an unemployed waiter and train him tO be a doctor in a few weeks. But even if you cannot close the gap, maybe you can close others, and doing so would be to the benefit of all concerned. That seems to be the case in Sweden: when f01 ℃ ed to furlough 90 percent of their cabin staff, Scandinavian Airline decided to start up a short retammg program that reskilled the laid-off workers t0 suppoft hospital staff. The effort was a collective one and involved Other compames as well a Swedish university.",
